--
-- Table structure for table `perfil`
--

DROP TABLE IF EXISTS `perfil`;
CREATE TABLE `perfil` (
  `id_perfil` int NOT NULL AUTO_INCREMENT COMMENT 'identificador do perfil de cadastro',
  `nome` varchar(30) NOT NULL COMMENT 'nome do perfil',
  `descricao` varchar(260) DEFAULT NULL,
  `ativo` tinyint NOT NULL,
  `data_criacao` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_perfil`)
) ENGINE=InnoDB AUTO_INCREMENT=3001 DEFAULT CHARSET=utf8mb3;

